// Group food and drinks by category for Checkbox.Group options
const groupedFoodAndDrinks = {};
allFoodAndDrinksData.forEach((item) => {
  if (!groupedFoodAndDrinks[item.category]) {
    groupedFoodAndDrinks[item.category] = [];
  }
  groupedFoodAndDrinks[item.category].push({
    label: `${item.name} (THB ${item.price})`,
    value: item.name, // Use name as value for checkbox
    price: item.price, // Keep price for total calculation in parent
  });
});

const foodAndDrinksCategoryOrder = ["Food", "Drinks"];

export default function FoodAndDrinksModal({
  open,
  onClose,
  onSave, // New prop: callback when selection is saved
  initialSelectedItems, // New prop: items already selected to pre-check
}) {
  const [form] = Form.useForm();

  // Set initial values for the form when modal opens or initialSelectedItems change
  React.useEffect(() => {
    if (open) {
      form.setFieldsValue({
        food_and_drinks: initialSelectedItems || [], // Ensure it's an array, even if null/undefined
      });
    } else {
      // Reset form when modal is closed to clear previous selections for next open
      form.resetFields();
    }
  }, [open, initialSelectedItems, form]);

  const handleFinish = (values) => {
    console.log("FoodAndDrinksModal: Form submitted with values:", values); // เพิ่ม console.log สำหรับ Debug
    onSave(values.food_and_drinks || []); // Call onSave with selected items
    onClose(); // Close the modal
  };

  const handleCancel = () => {
    onClose(); // Just close the modal on cancel
  };

  return (
    <Modal
      title="เลือกอาหารและเครื่องดื่ม"
      open={open}
      onOk={() => form.submit()} // Submit the form inside the modal
      onCancel={handleCancel}
      cancelText="ยกเลิก"
      okText="ยืนยันการเลือก"
      destroyOnClose={false}
      width={600}
    >
      <Divider />
      <p>ราคาอาหารและเครื่องดื่ม คูณตามจำนวนที่นั่ง</p>
      <Form
        form={form}
        layout="vertical"
        onFinish={handleFinish}
        initialValues={{
          food_and_drinks: initialSelectedItems || [], // Ensure initial values are set on first render
        }}
      >
        <Form.Item name="food_and_drinks">
          <Checkbox.Group style={{ width: "100%" }}>
            {Object.keys(groupedFoodAndDrinks).length > 0 ? (
              foodAndDrinksCategoryOrder.map((category) => {
                const itemsInThisCategory = groupedFoodAndDrinks[category];
                if (itemsInThisCategory && itemsInThisCategory.length > 0) {
                  return (
                    <div key={category} style={{ marginBottom: "15px" }}>
                      <Title
                        level={5}
                        style={{ fontSize: "16px", marginBottom: "8px" }}
                      >
                        {category}
                      </Title>
                      <Row gutter={[10, 10]}>
                        {itemsInThisCategory.map((option) => (
                          <Col key={option.value} xs={24} sm={12}>
                            <Checkbox value={option.value}>
                              {option.label}
                            </Checkbox>
                          </Col>
                        ))}
                      </Row>
                    </div>
                  );
                }
                return null;
              })
            ) : (
              <Text type="secondary">ไม่มีรายการอาหารและเครื่องดื่ม</Text>
            )}
          </Checkbox.Group>
        </Form.Item>
      </Form>
    </Modal>
  );
}

export { allFoodAndDrinksData };
