export default function RoomDetailsPage() {
  const { id } = useParams();
  const [room, setRoom] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [bookedList, setBookList] = useState([]);
  const [isBookingModalOpen, setIsBookingModalOpen] = useState(false);
  const [isBookedListModalOpen, setIsBookedListModalOpen] = useState(false);

  useEffect(() => {
    const fetchRoomDetails = async () => {
      try {
        setLoading(true);
        const response = await baseAPI.get(`/meetingrooms/${id}`);
        setRoom(response.data);
      } catch (err) {
        console.error("Failed to fetch room details:", err);
        setError("ไม่สามารถโหลดข้อมูลห้องประชุมได้ กรุณาลองใหม่อีกครั้ง");
      } finally {
        setLoading(false);
      }
    };

    if (id) {
      fetchRoomDetails();
    }
  }, [id]);

  const fethBookingList = async () => {
    setLoading(true);
    const result = await baseAPI.get(`/booking-rooms/rooms/${id}`);
    // console.log('List', result.data)

    setBookList(result.data);
    setIsBookedListModalOpen(result.data);
    setLoading(false);
  };

  const groupedAllAmenities = {};
  allAmenitiesData.forEach((amenity) => {
    if (!groupedAllAmenities[amenity.category]) {
      groupedAllAmenities[amenity.category] = [];
    }
    groupedAllAmenities[amenity.category].push(amenity);
  });

  const categoryOrder = ["Display", "Sound", "Video Conferencing", "Other"];

  const handleOpenBookingModal = () => {
    console.log(room);
    setIsBookingModalOpen(true);
  };

  const handleCloseBookingModal = () => {
    setIsBookingModalOpen(false);
  };

  const handleFinishBooking = (bookingData) => {
    setIsBookingModalOpen(false);
    notification.success({
      message: `จองห้อง ${bookingData.title || room.title} สำเร็จ!`,
      description:
        "เจ้าหน้าที่จะติดต่อกลับไปเพื่อยืนยันการจองในเวลาทำการ กรุณารอการติดต่อกลับ",
      duration: 5,
    });
  };

  const handleOpenBookedList = () => {
    fethBookingList();
  };

  if (loading) {
    return (
      <div style={{ padding: "50px", textAlign: "center" }}>
        <SimpleLoading tip="กำลังโหลดข้อมูลห้องประชุม..." />
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ padding: "50px", textAlign: "center" }}>
        <Title level={4} type="danger">
          {error}
        </Title>
        <Link to="/meetingrooms">
          <Button type="primary" icon={<ArrowLeftOutlined />}>
            กลับหน้าจองห้องประชุม
          </Button>
        </Link>
      </div>
    );
  }

  if (!room) {
    return (
      <div style={{ padding: "50px", textAlign: "center" }}>
        <Title level={4}>ไม่พบข้อมูลห้องประชุม</Title>
        <Link to="/meetingrooms">
          <Button type="primary" icon={<ArrowLeftOutlined />}>
            กลับหน้าจองห้องประชุม
          </Button>
        </Link>
      </div>
    );
  }

  return (
    <div style={{ padding: "20px" }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "20px",
        }}
      >
        <Link to="/meetingrooms">
          <Button type="link" icon={<ArrowLeftOutlined />}>
            กลับหน้าจองห้องประชุม
          </Button>
        </Link>
      </div>

      <Card
        title={<Title level={2}>{room.title}</Title>}
        className="room-details-card"
        style={{ maxWidth: "1000px", margin: "0 auto", padding: "20px" }}
      >
        <Row gutter={[24, 24]}>
          <Col xs={24} md={12}>
            {room.cover && (
              <Image
                src={room.cover}
                alt={room.title}
                style={{
                  width: "100%",
                  maxHeight: "400px",
                  borderRadius: "8px",
                  objectFit: "cover",
                }}
              />
            )}
          </Col>
          <Col xs={24} md={12}>
            <Descriptions bordered column={1}>
              <Descriptions.Item label="ขนาดห้อง">
                {room.size || "-"}
              </Descriptions.Item>
              <Descriptions.Item label="รองรับผู้เข้าประชุม">
                {room.capacity} ที่นั่ง
              </Descriptions.Item>
              <Descriptions.Item label="ราคาต่อชั่วโมง">
                THB {room.price} / ชั่วโมง
              </Descriptions.Item>
              <Descriptions.Item label="รายละเอียด">
                {room.description}
              </Descriptions.Item>
              <Descriptions.Item label="บริการ">
                {room.promotion || "-"}
              </Descriptions.Item>
            </Descriptions>
            <Space
              style={{
                display: "flex",
                justifyContent: "center",
                marginTop: "20px",
              }}
            >
              <Button
                // type="primary"
                size="large"
                icon={<ClockCircleOutlined />}
                onClick={handleOpenBookedList}
              >
                ดูคิวจอง
              </Button>
              <Button
                type="primary"
                size="large"
                icon={<CalendarOutlined />}
                onClick={handleOpenBookingModal}
              >
                จองห้องนี้
              </Button>
            </Space>
          </Col>
        </Row>

        <Divider orientation="left">
          <Title level={3}>สิ่งอำนวยความสะดวกภายในห้อง</Title>
        </Divider>

        {Object.keys(groupedAllAmenities).length > 0 ? (
          categoryOrder.map((category) => {
            const amenitiesInThisCategory = groupedAllAmenities[category];
            if (amenitiesInThisCategory && amenitiesInThisCategory.length > 0) {
              return (
                <div key={category} style={{ marginBottom: "30px" }}>
                  <Title level={4}>{category}</Title>
                  <Row gutter={[16, 16]}>
                    {amenitiesInThisCategory.map((amenity) => (
                      <Col xs={24} sm={12} md={12} lg={8} key={amenity.id}>
                        <Card
                          hoverable
                          style={{ textAlign: "center", height: "100%" }}
                          cover={
                            <Image
                              alt={amenity.name}
                              src={amenity.icon}
                              style={{
                                padding: "10px",
                                height: "100px",
                                objectFit: "contain",
                              }}
                              preview={false}
                            />
                          }
                        >
                          <Card.Meta
                            title={<Text strong>{amenity.name}</Text>}
                            description={
                              <>
                                <Text type="secondary">
                                  {amenity.description}
                                </Text>
                                {/* เพิ่มส่วนแสดงราคาตรงนี้ */}
                                <div style={{ marginTop: "8px" }}>
                                  {amenity.is_free ? (
                                    <Text strong type="success">
                                      Free
                                    </Text>
                                  ) : (
                                    <div
                                      style={{
                                        display: "flex",
                                        flexDirection: "column",
                                      }}
                                    >
                                      <Text strong type="danger">
                                        +THB {amenity.price}
                                      </Text>
                                      <Text type="secondary">
                                        {amenity.deposit ? "(มีค่ามัดจำ)" : ""}
                                      </Text>
                                    </div>
                                  )}
                                </div>
                              </>
                            }
                          />
                        </Card>
                      </Col>
                    ))}
                  </Row>
                </div>
              );
            }
            return null;
          })
        ) : (
          <div style={{ textAlign: "center", padding: "20px" }}>
            <Text type="secondary">
              ไม่มีข้อมูลสิ่งอำนวยความสะดวกที่กำหนดไว้
            </Text>
          </div>
        )}
      </Card>

      <BookingRoomModal
        open={isBookingModalOpen}
        onClose={handleCloseBookingModal}
        onFinish={handleFinishBooking}
        // selectedRoomId={room ? room.id : null}
        // roomPrice={room ? room.price : 0}
        room={room}
      />

      <MeetingRoomCalendarModal
        open={isBookedListModalOpen}
        onClose={setIsBookedListModalOpen}
        bookedList={bookedList}
      />
    </div>
  );
}
